# Source: Rubio-Enterprises/standards, template/scripts/common/knowledgebase-paths.sh
# From a consumer root: knowledgebase_excludes emits NUL-delimited treefmt
# globs; seed_knowledgebase_markers DEST seeds empty markers into a scratch
# render. Neither interface reads or copies knowledgebase content. Both are
# inactive unless has_knowledgebase is explicitly true. Keep bash 3.2 support.

_knowledgebase_enabled() {
  [ -f .copier-answers.yml ] &&
    grep -Eq '^has_knowledgebase:[[:space:]]*true([[:space:]]*(#.*)?)?$' .copier-answers.yml
}

_knowledgebase_git() (
  # Resolve from CWD, not the repository context exported by a parent hook.
  unset GIT_INDEX_FILE GIT_DIR GIT_WORK_TREE GIT_COMMON_DIR \
    GIT_OBJECT_DIRECTORY GIT_ALTERNATE_OBJECT_DIRECTORIES GIT_PREFIX
  git "$@"
)

_knowledgebase_markers() {
  local listing candidate failed=0
  listing="$(mktemp)" || return 1
  if _knowledgebase_git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
    if ! _knowledgebase_git ls-files -z -- ':(glob)**/.copier-answers.knowledgebase.yml' >"$listing"; then
      rm -f "$listing"
      return 1
    fi
  elif ! find . \( -type d \( -name .git -o -name node_modules -o -name fixtures -o -name testdata \) \) \
    -prune -o -type f -name .copier-answers.knowledgebase.yml -print0 >"$listing"; then
    rm -f "$listing"
    return 1
  fi
  while IFS= read -r -d '' candidate; do
    candidate="${candidate#./}"
    case "$candidate" in
    fixtures/* | */fixtures/* | testdata/* | */testdata/*) continue ;;
    esac
    [ -f "$candidate" ] || continue
    if ! printf '%s\0' "$candidate"; then
      failed=1
      break
    fi
  done <"$listing"
  rm -f "$listing"
  [ "$failed" -eq 0 ]
}

_knowledgebase_glob_prefix() {
  local prefix="$1" escaped="" character
  # Metadata paths are literal. A bracket, wildcard or brace in a folder name
  # must not widen protection to a neighbouring application directory.
  while [ -n "$prefix" ]; do
    character="${prefix:0:1}"
    prefix="${prefix:1}"
    case "$character" in
    \\ | '*' | '?' | '[' | ']' | '{' | '}') escaped="$escaped\\$character" ;;
    *) escaped="$escaped$character" ;;
    esac
  done
  printf '%s' "$escaped"
}

knowledgebase_excludes() {
  _knowledgebase_enabled || return 0
  local listing candidate prefix failed=0
  listing="$(mktemp)" || return 1
  if ! _knowledgebase_markers >"$listing"; then
    rm -f "$listing"
    return 1
  fi
  while IFS= read -r -d '' candidate; do
    prefix=""
    case "$candidate" in */*) prefix="${candidate%/*}/" ;; esac
    if ! prefix="$(_knowledgebase_glob_prefix "$prefix")" ||
      ! printf '%s\0' "${prefix}.copier-answers.knowledgebase.yml" "${prefix}.vscode/**" "${prefix}assets/**"; then
      failed=1
      break
    fi
  done <"$listing"
  rm -f "$listing"
  [ "$failed" -eq 0 ]
}

seed_knowledgebase_markers() {
  _knowledgebase_enabled || return 0
  local destination="$1" source_root destination_root listing candidate path failed=0
  source_root="$(pwd -P)" || return 1
  destination_root="$(cd "$destination" && pwd -P)" || return 1
  if [ "$source_root" = "$destination_root" ]; then
    echo 'seed_knowledgebase_markers: destination must be a separate scratch render.' >&2
    return 1
  fi
  listing="$(mktemp)" || return 1
  if ! _knowledgebase_markers >"$listing"; then
    rm -f "$listing"
    return 1
  fi
  while IFS= read -r -d '' candidate; do
    path="$destination_root/$candidate"
