    if [ -e "$path" ] || [ -L "$path" ]; then continue; fi
    if ! mkdir -p "${path%/*}" || ! : >"$path"; then
      failed=1
      break
    fi
  done <"$listing"
  rm -f "$listing"
  [ "$failed" -eq 0 ]
}
